    ));
  }, [user]);

  const updateDeliveryStatus = useCallback((status: DeliveryStatus) => {
    if (user?.role !== UserRole.DRIVER) return;
    setDrivers(prev => prev.map(d => 
      d.id === user.id ? { ...d, status } : d
    ));
  }, [user]);

  return (
    <LogisticsContext.Provider value={{ 
      user, 
      drivers, 
      login, 
      logout, 
      updateLocation, 
      toggleStatus, 
      updateCargo,
      updateDeliveryStatus 
    }}>
      {children}
    </LogisticsContext.Provider>
  );
};

export const useLogistics = () => {
  const context = useContext(LogisticsContext);
  if (!context) throw new Error('useLogistics must be used within a LogisticsProvider');
  return context;
};

import React, { useState, useEffect } from 'react';
import { useLogistics } from '../services/logisticsContext';
import { Button } from './Button';
import { CargoItem, DeliveryStatus } from '../types';

export const DriverApp: React.FC = () => {
  const { user, drivers, toggleStatus, updateLocation, updateCargo, updateDeliveryStatus, logout } = useLogistics();
  const currentDriver = drivers.find(d => d.id === user?.id);
  const isOnline = currentDriver?.isOnline || false;

  const [cargoName, setCargoName] = useState('');
  const [cargoQty, setCargoQty] = useState('');
  const [cargoDest, setCargoDest] = useState('');

  // Geolocation Loop
  useEffect(() => {
    let watchId: number;

    if (isOnline) {
      if ('geolocation' in navigator) {
        watchId = navigator.geolocation.watchPosition(
          (position) => {
            updateLocation(position.coords.latitude, position.coords.longitude);
          },
          (error) => console.error("Geo error:", error),
          { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
        );
      }
    }

    return () => {
      if (watchId) navigator.geolocation.clearWatch(watchId);
    };
  }, [isOnline, updateLocation]);

  const handleAddCargo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!cargoName || !cargoQty) return;

    const newItem: CargoItem = {
      id: Math.random().toString(36).substr(2, 9),
      name: cargoName,
      quantity: parseInt(cargoQty),
      destination: cargoDest || 'Unspecified'
    };

    updateCargo([...(currentDriver?.cargo || []), newItem]);
    setCargoName('');
    setCargoQty('');
    setCargoDest('');
  };

  const removeCargo = (id: string) => {
    updateCargo((currentDriver?.cargo || []).filter(c => c.id !== id));
  };

  const statusColors: Record<DeliveryStatus, string> = {
    'IN_TRANSIT': 'bg-blue-600 border-blue-400 text-white',
    'DELIVERED': 'bg-emerald-600 border-emerald-400 text-white',
    'DELAYED': 'bg-amber-600 border-amber-400 text-white',
  };

  return (
    <div className="h-full flex flex-col bg-slate-900 text-white max-w-md mx-auto w-full shadow-2xl relative">
      {/* Header */}
      <header className="p-6 bg-slate-800 border-b border-slate-700 flex justify-between items-center sticky top-0 z-10">
        <div>
          <h1 className="text-xl font-bold tracking-tight">Driver Console</h1>
          <p className="text-xs text-slate-400">ID: {user?.id.slice(0, 8)}...</p>
        </div>
        <button onClick={logout} className="text-xs text-slate-400 hover:text-white">Sign Out</button>
      </header>

      <div className="flex-1 overflow-y-auto p-6 space-y-8">

        {/* Status Toggle */}
        <section className="text-center space-y-4">
          <div className={`inline-flex p-1 rounded-full ${isOnline ? 'bg-emerald-500/10' : 'bg-slate-800'}`}>
            <div className={`px-4 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${isOnline ? 'text-emerald-500' : 'text-slate-500'}`}>
              {isOnline ? 'Broadcasting Live' : 'Offline'}
            </div>
          </div>

          <button 
            onClick={() => toggleStatus(!isOnline)}
            className={`w-32 h-32 rounded-full flex flex-col items-center justify-center mx-auto transition-all duration-300 shadow-2xl ${
              isOnline 
                ? 'bg-gradient-to-br from-rose-500 to-red-600 shadow-rose-500/30 scale-100' 
                : 'bg-gradient-to-br from-emerald-500 to-green-600 shadow-emerald-500/30 hover:scale-105'
            }`}
          >
            <span className="text-2xl font-bold">{isOnline ? 'STOP' : 'START'}</span>
            <span className="text-xs opacity-80 mt-1">{isOnline ? 'End Shift' : 'Start Trip'}</span>
          </button>
        </section>

        {/* Delivery Status Selector */}
        {isOnline && (
          <section className="space-y-2">
            <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-wider text-center">Update Status</h2>
            <div className="grid grid-cols-3 gap-2">
              {(['IN_TRANSIT', 'DELIVERED', 'DELAYED'] as DeliveryStatus[]).map((status) => (
                <button
                  key={status}
                  onClick={() => updateDeliveryStatus(status)}
                  className={`py-3 px-2 rounded-lg text-xs font-bold border-2 transition-all ${
                    currentDriver?.status === status 
                      ? statusColors[status] 
                      : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-700'
                  }`}
                >
                  {status.replace('_', ' ')}
                </button>
              ))}
            </div>
          </section>
        )}

        {/* Cargo Manifest */}
        <section className="space-y-4 pt-4 border-t border-slate-800">
          <h2 className="text-lg font-semibold text-slate-300">Current Manifest</h2>

          <form onSubmit={handleAddCargo} className="grid grid-cols-12 gap-2">
            <input 
              className="col-span-12 bg-slate-800 border border-slate-700 rounded p-3 text-sm focus:border-blue-500 outline-none" 
              placeholder="Item Name" 
              value={cargoName} 
              onChange={e => setCargoName(e.target.value)} 
            />
            <input 
              className="col-span-4 bg-slate-800 border border-slate-700 rounded p-3 text-sm focus:border-blue-500 outline-none" 
              type="number" 
              placeholder="Qty" 
              value={cargoQty} 
              onChange={e => setCargoQty(e.target.value)} 
            />
            <input 
              className="col-span-8 bg-slate-800 border border-slate-700 rounded p-3 text-sm focus:border-blue-500 outline-none" 
              placeholder="Dest." 
              value={cargoDest} 
              onChange={e => setCargoDest(e.target.value)} 
            />
            <Button type="submit" fullWidth className="col-span-12 py-2 text-sm" variant="secondary">
              + Log Cargo
            </Button>
          </form>

          <div className="space-y-2 mt-4">
            {currentDriver?.cargo?.length === 0 && (
              <p className="text-center text-slate-600 text-sm py-4">No cargo logged.</p>
            )}
            {currentDriver?.cargo?.map(item => (
              <div key={item.id} className="bg-slate-800/50 p-3 rounded flex justify-between items-center border border-slate-700">
                <div>
                  <div className="font-medium text-slate-200">{item.name}</div>
                  <div className="text-xs text-slate-500">{item.quantity} units &bull; {item.destination}</div>
                </div>
                <button 
                  onClick={() => removeCargo(item.id)}
                  className="text-slate-500 hover:text-rose-400 p-2"
                >
                  &times;
                </button>
              </div>
            ))}
          </div>
        </section>

        {/* Debug Info */}
        <div className="text-[10px] text-slate-600 font-mono text-center pt-8 pb-4">
          LAT: {currentDriver?.latitude.toFixed(6)} | LNG: {currentDriver?.longitude.toFixed(6)}
        </div>
      </div>
    </div>
  );
};

