import React, { useEffect, useRef, useState } from 'react';
import { Driver } from '../types';

/* 
  NOTE: This component handles both Real Google Maps and a 
  high-fidelity Simulated Map for demo purposes (if no API key).
*/

declare global {
  interface Window {
    google: any;
  }
}

interface MapProps {
  drivers: Driver[];
  selectedDriverId: string | null;
  onSelectDriver: (id: string) => void;
}

export const Map: React.FC<MapProps> = ({ drivers, selectedDriverId, onSelectDriver }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const [mapInstance, setMapInstance] = useState<any | null>(null);
  const markersRef = useRef<{ [id: string]: any }>({});
  const [apiLoaded, setApiLoaded] = useState(false);

  // Check if Google Maps is available
  useEffect(() => {
    if (window.google && window.google.maps) {
      setApiLoaded(true);
    } else {
      // Check periodically (since index.html might load it async)
      const interval = setInterval(() => {
        if (window.google && window.google.maps) {
          setApiLoaded(true);
          clearInterval(interval);
        }
      }, 500);
      return () => clearInterval(interval);
    }
  }, []);

  // Initialize Map
  useEffect(() => {
    if (apiLoaded && mapRef.current && !mapInstance) {
      const map = new window.google.maps.Map(mapRef.current, {
        center: { lat: 17.0746, lng: -61.8175 }, // Centered on Antigua
        zoom: 12,
        styles: [
          { elementType: "geometry", stylers: [{ color: "#242f3e" }] },
          { elementType: "labels.text.stroke", stylers: [{ color: "#242f3e" }] },
          { elementType: "labels.text.fill", stylers: [{ color: "#746855" }] },
          {
            featureType: "administrative.locality",
            elementType: "labels.text.fill",
            stylers: [{ color: "#d59563" }],
          },
          {
            featureType: "road",
            elementType: "geometry",
            stylers: [{ color: "#38414e" }],
          },
          {
            featureType: "road",
            elementType: "geometry.stroke",
            stylers: [{ color: "#212a37" }],
          },
          {
            featureType: "water",
            elementType: "geometry",
            stylers: [{ color: "#17263c" }],
          },
        ],
        disableDefaultUI: true,
      });
      setMapInstance(map);
    }
  }, [apiLoaded, mapInstance]);

  // Update Markers
  useEffect(() => {
    if (!mapInstance) return;

    drivers.forEach(driver => {
      // If offline, remove marker or make it grey
      if (!driver.isOnline) {
        if (markersRef.current[driver.id]) {
          markersRef.current[driver.id].setMap(null);
          delete markersRef.current[driver.id];
        }
        return;
      }

      const position = { lat: driver.latitude, lng: driver.longitude };

      if (markersRef.current[driver.id]) {
        // Update existing
        markersRef.current[driver.id].setPosition(position);
        markersRef.current[driver.id].setIcon(getIcon(driver.id === selectedDriverId));
      } else {
        // Create new
        const marker = new window.google.maps.Marker({
          position,
          map: mapInstance,
          title: driver.name,
          icon: getIcon(driver.id === selectedDriverId),
        });

        marker.addListener("click", () => {
          onSelectDriver(driver.id);
        });

        markersRef.current[driver.id] = marker;
      }
    });

    // Cleanup removed drivers
    Object.keys(markersRef.current).forEach(id => {
      if (!drivers.find(d => d.id === id)) {
        markersRef.current[id].setMap(null);
        delete markersRef.current[id];
      }
    });

  }, [drivers, mapInstance, selectedDriverId, onSelectDriver]);

  const getIcon = (isSelected: boolean) => {
    return {
      path: window.google.maps.SymbolPath.FORWARD_CLOSED_ARROW,
      scale: 6,
      fillColor: isSelected ? "#3b82f6" : "#10b981", // Blue if selected, Green otherwise
      fillOpacity: 1,
      strokeWeight: 2,
      strokeColor: "#ffffff",
      rotation: 0, // In a real app, use driver.heading
    };
  };

  if (!apiLoaded) {
    // FALLBACK SIMULATION MAP (If no API Key provided)
    return <FallbackMap drivers={drivers} selectedDriverId={selectedDriverId} onSelectDriver={onSelectDriver} />;
  }

  return <div ref={mapRef} className="w-full h-full" />;
};

// --- FALLBACK VISUALIZATION ---
// This ensures the app is usable immediately without configuring an API key
const FallbackMap: React.FC<MapProps> = ({ drivers, selectedDriverId, onSelectDriver }) => {
  // Projection centered on Antigua
  // Center Lat: 17.07, Center Lng: -61.81
  const centerLat = 17.07;
  const centerLng = -61.81;
  const scale = 5000; // Adjusted for smaller island scale vs NYC

  return (
    <div className="w-full h-full bg-[#1e293b] relative overflow-hidden group">
      {/* Grid Pattern */}
      <div className="absolute inset-0 opacity-10" 
           style={{ backgroundImage: 'radial-gradient(#475569 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>

      {/* Simulation Text */}
      <div className="absolute top-4 left-4 z-10 bg-black/50 backdrop-blur px-3 py-1 rounded text-xs text-slate-400 border border-slate-700">
        Demo Mode (Antigua)
      </div>

      {/* Render Drivers */}
      {drivers.filter(d => d.isOnline).map(driver => {
        const x = 50 + (driver.longitude - centerLng) * scale / 10; // % offset
        const y = 50 - (driver.latitude - centerLat) * scale / 6; // % offset
        const isSelected = driver.id === selectedDriverId;

        let markerColor = 'bg-emerald-500';
        if (driver.status === 'DELAYED') markerColor = 'bg-amber-500';
        if (driver.status === 'DELIVERED') markerColor = 'bg-blue-500';

        return (
          <button
            key={driver.id}
            onClick={() => onSelectDriver(driver.id)}
            className="absolute transform -translate-x-1/2 -translate-y-1/2 transition-all duration-1000 ease-linear hover:scale-110 z-20"
            style={{ left: `${x}%`, top: `${y}%` }}
          >
            <div className={`relative flex items-center justify-center w-8 h-8 rounded-full shadow-lg border-2 ${isSelected ? 'border-white z-30 scale-110' : 'border-transparent'} ${markerColor}`}>
              <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
              {/* Pulse effect */}
              {isSelected && <span className={`absolute inline-flex h-full w-full rounded-full opacity-75 animate-ping ${markerColor}`}></span>}
            </div>
            <div className="absolute top-10 left-1/2 -translate-x-1/2 bg-slate-900 text-white text-[10px] px-2 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap">
              {driver.name}
            </div>
          </button>
        );
      })}
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { useLogistics } from '../services/logisticsContext';
import { Button } from './Button';
import { CargoItem, DeliveryStatus } from '../types';

export const DriverApp: React.FC = () => {
  const { user, drivers, toggleStatus, updateLocation, updateCargo, updateDeliveryStatus, logout } = useLogistics();
  const currentDriver = drivers.find(d => d.id === user?.id);
  const isOnline = currentDriver?.isOnline || false;

  const [cargoName, setCargoName] = useState('');
  const [cargoQty, setCargoQty] = useState('');
  const [cargoDest, setCargoDest] = useState('');

  // Geolocation Loop
  useEffect(() => {
    let watchId: number;

    if (isOnline) {
      if ('geolocation' in navigator) {
        watchId = navigator.geolocation.watchPosition(
          (position) => {
            updateLocation(position.coords.latitude, position.coords.longitude);
          },
          (error) => console.error("Geo error:", error),
          { enableHighAccuracy: true, timeout: 5000, maximumAge: 0 }
        );
      }
    }

    return () => {
      if (watchId) navigator.geolocation.clearWatch(watchId);
    };
  }, [isOnline, updateLocation]);

  const handleAddCargo = (e: React.FormEvent) => {
    e.preventDefault();
    if (!cargoName || !cargoQty) return;

    const newItem: CargoItem = {
      id: Math.random().toString(36).substr(2, 9),
      name: cargoName,
      quantity: parseInt(cargoQty),
      destination: cargoDest || 'Unspecified'
    };

    updateCargo([...(currentDriver?.cargo || []), newItem]);
    setCargoName('');
    setCargoQty('');
    setCargoDest('');
  };

  const removeCargo = (id: string) => {
    updateCargo((currentDriver?.cargo || []).filter(c => c.id !== id));
  };

  const statusConfig: Record<DeliveryStatus, { color: string, icon: React.ReactNode, label: string }> = {
    'IN_TRANSIT': {
      color: 'bg-blue-600 border-blue-400 text-white shadow-blue-900/50',
      label: 'In Transit',
      icon: (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path d="M9 17a2 2 0 11-4 0 2 2 0 014 0zM19 17a2 2 0 11-4 0 2 2 0 014 0z" />
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16V6a1 1 0 00-1-1H4a1 1 0 00-1 1v10a1 1 0 001 1h1m8-1a1 1 0 01-1 1H9m4-1V8a1 1 0 011-1h2.586a1 1 0 01.707.293l3.414 3.414a1 1 0 01.293.707V16a1 1 0 01-1 1h-1m-6-1a1 1 0 001 1h1M5 17a2 2 0 104 0m-4 0a2 2 0 114 0m6 0a2 2 0 104 0m-4 0a2 2 0 114 0" />
        </svg>
      )
    },
    'DELIVERED': {
      color: 'bg-emerald-600 border-emerald-400 text-white shadow-emerald-900/50',
      label: 'Delivered',
      icon: (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      )
    },
    'DELAYED': {
      color: 'bg-amber-600 border-amber-400 text-white shadow-amber-900/50',
      label: 'Delayed',
      icon: (
        <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5 mb-1" fill="none" viewBox="0 0 24 24" stroke="currentColor">
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8v4l3 3m6-3a9 9 0 11-18 0 9 9 0 0118 0z" />
        </svg>
      )
    },
  };

  return (
    <div className="h-full flex flex-col bg-slate-900 text-white max-w-md mx-auto w-full shadow-2xl relative">
      {/* Header */}
      <header className="p-6 bg-slate-800 border-b border-slate-700 flex justify-between items-center sticky top-0 z-10">
        <div>
          <h1 className="text-xl font-bold tracking-tight">Driver Console</h1>
          <p className="text-xs text-slate-400">ID: {user?.id.slice(0, 8)}...</p>
        </div>
        <button onClick={logout} className="text-xs text-slate-400 hover:text-white">Sign Out</button>
      </header>

      <div className="flex-1 overflow-y-auto p-6 space-y-8">

        {/* Status Toggle */}
        <section className="text-center space-y-4">
          <div className={`inline-flex p-1 rounded-full ${isOnline ? 'bg-emerald-500/10' : 'bg-slate-800'}`}>
            <div className={`px-4 py-1 rounded-full text-xs font-bold uppercase tracking-wider ${isOnline ? 'text-emerald-500' : 'text-slate-500'}`}>
              {isOnline ? 'Broadcasting Live' : 'Offline'}
            </div>
          </div>

          <button 
            onClick={() => toggleStatus(!isOnline)}
            className={`w-32 h-32 rounded-full flex flex-col items-center justify-center mx-auto transition-all duration-300 shadow-2xl ${
              isOnline 
                ? 'bg-gradient-to-br from-rose-500 to-red-600 shadow-rose-500/30 scale-100' 
                : 'bg-gradient-to-br from-emerald-500 to-green-600 shadow-emerald-500/30 hover:scale-105'
            }`}
          >
            <span className="text-2xl font-bold">{isOnline ? 'STOP' : 'START'}</span>
            <span className="text-xs opacity-80 mt-1">{isOnline ? 'End Shift' : 'Start Trip'}</span>
          </button>
        </section>

        {/* Delivery Status Selector */}
        {isOnline && (
          <section className="space-y-3">
            <h2 className="text-xs font-semibold text-slate-500 uppercase tracking-wider text-center">Current Status</h2>
            <div className="grid grid-cols-3 gap-2">
              {(['IN_TRANSIT', 'DELIVERED', 'DELAYED'] as DeliveryStatus[]).map((status) => {
                const isActive = currentDriver?.status === status;
                const config = statusConfig[status];

                return (
                  <button
                    key={status}
                    onClick={() => updateDeliveryStatus(status)}
                    className={`py-3 px-2 rounded-xl text-xs font-bold border transition-all flex flex-col items-center justify-center shadow-lg ${
                      isActive 
                        ? config.color
                        : 'bg-slate-800 border-slate-700 text-slate-400 hover:bg-slate-750 hover:border-slate-600'
                    }`}
                  >
                    {config.icon}
                    {config.label}
                  </button>
                );
              })}
            </div>
          </section>
        )}

        {/* Cargo Manifest */}
        <section className="space-y-4 pt-4 border-t border-slate-800">
          <h2 className="text-lg font-semibold text-slate-300">Current Manifest</h2>

          <form onSubmit={handleAddCargo} className="grid grid-cols-12 gap-2">
            <input 
              className="col-span-12 bg-slate-800 border border-slate-700 rounded p-3 text-sm focus:border-blue-500 outline-none placeholder-slate-500" 
              placeholder="Item Name" 
              value={cargoName} 
              onChange={e => setCargoName(e.target.value)} 
            />
            <input 
              className="col-span-4 bg-slate-800 border border-slate-700 rounded p-3 text-sm focus:border-blue-500 outline-none placeholder-slate-500" 
              type="number" 
              placeholder="Qty" 
              value={cargoQty} 
              onChange={e => setCargoQty(e.target.value)} 
            />
            <input 
              className="col-span-8 bg-slate-800 border border-slate-700 rounded p-3 text-sm focus:border-blue-500 outline-none placeholder-slate-500" 
              placeholder="Dest." 
              value={cargoDest} 
              onChange={e => setCargoDest(e.target.value)} 
            />
            <Button type="submit" fullWidth className="col-span-12 py-2 text-sm" variant="secondary">
              + Log Cargo
            </Button>
          </form>

          <div className="space-y-2 mt-4">
            {currentDriver?.cargo?.length === 0 && (
              <p className="text-center text-slate-600 text-sm py-4">No cargo logged.</p>
            )}
            {currentDriver?.cargo?.map(item => (
              <div key={item.id} className="bg-slate-800/50 p-3 rounded flex justify-between items-center border border-slate-700">
                <div>
                  <div className="font-medium text-slate-200">{item.name}</div>
                  <div className="text-xs text-slate-500">{item.quantity} units &bull; {item.destination}</div>
                </div>
                <button 
                  onClick={() => removeCargo(item.id)}
                  className="text-slate-500 hover:text-rose-400 p-2"
                >
                  &times;
                </button>
              </div>
            ))}
          </div>
        </section>

        {/* Debug Info */}
        <div className="text-[10px] text-slate-600 font-mono text-center pt-8 pb-4">
          LAT: {currentDriver?.latitude.toFixed(6)} | LNG: {currentDriver?.longitude.toFixed(6)}
        </div>
      </div>
    </div>
  );
};

import React, { useEffect, useRef, useState } from 'react';
import { Driver } from '../types';

/* 
  NOTE: This component handles both Real Google Maps and a 
  high-fidelity Simulated Map for demo purposes (if no API key).
*/

declare global {
  interface Window {
    google: any;
  }
}

interface MapProps {
  drivers: Driver[];
  selectedDriverId: string | null;
  onSelectDriver: (id: string) => void;
}

export const Map: React.FC<MapProps> = ({ drivers, selectedDriverId, onSelectDriver }) => {
  const mapRef = useRef<HTMLDivElement>(null);
  const [mapInstance, setMapInstance] = useState<any | null>(null);
  const markersRef = useRef<{ [id: string]: any }>({});
  const [apiLoaded, setApiLoaded] = useState(false);

  // Check if Google Maps is available
  useEffect(() => {
    if (window.google && window.google.maps) {
      setApiLoaded(true);
    } else {
      // Check periodically (since index.html might load it async)
      const interval = setInterval(() => {
        if (window.google && window.google.maps) {
          setApiLoaded(true);
          clearInterval(interval);
        }
      }, 500);
      return () => clearInterval(interval);
    }
  }, []);

  // Initialize Map
  useEffect(() => {
    if (apiLoaded && mapRef.current && !mapInstance) {
      const map = new window.google.maps.Map(mapRef.current, {
        center: { lat: 17.0746, lng: -61.8175 }, // Centered on Antigua
        zoom: 12,
        styles: [
          { elementType: "geometry", stylers: [{ color: "#242f3e" }] },
          { elementType: "labels.text.stroke", stylers: [{ color: "#242f3e" }] },
          { elementType: "labels.text.fill", stylers: [{ color: "#746855" }] },
          {
            featureType: "administrative.locality",
            elementType: "labels.text.fill",
            stylers: [{ color: "#d59563" }],
          },
          {
            featureType: "road",
            elementType: "geometry",
            stylers: [{ color: "#38414e" }],
          },
          {
            featureType: "road",
            elementType: "geometry.stroke",
            stylers: [{ color: "#212a37" }],
          },
          {
            featureType: "water",
            elementType: "geometry",
            stylers: [{ color: "#17263c" }],
          },
        ],
        disableDefaultUI: true,
      });
      setMapInstance(map);
    }
  }, [apiLoaded, mapInstance]);

  // Update Markers
  useEffect(() => {
    if (!mapInstance) return;

    drivers.forEach(driver => {
      // If offline, remove marker or make it grey
      if (!driver.isOnline) {
        if (markersRef.current[driver.id]) {
          markersRef.current[driver.id].setMap(null);
          delete markersRef.current[driver.id];
        }
        return;
      }

      const position = { lat: driver.latitude, lng: driver.longitude };

      if (markersRef.current[driver.id]) {
        // Update existing
        markersRef.current[driver.id].setPosition(position);
        markersRef.current[driver.id].setIcon(getIcon(driver.id === selectedDriverId));
      } else {
        // Create new
        const marker = new window.google.maps.Marker({
          position,
          map: mapInstance,
          title: driver.name,
          icon: getIcon(driver.id === selectedDriverId),
        });

        marker.addListener("click", () => {
          onSelectDriver(driver.id);
        });

        markersRef.current[driver.id] = marker;
      }
    });

    // Cleanup removed drivers
    Object.keys(markersRef.current).forEach(id => {
      if (!drivers.find(d => d.id === id)) {
        markersRef.current[id].setMap(null);
        delete markersRef.current[id];
      }
    });

  }, [drivers, mapInstance, selectedDriverId, onSelectDriver]);

  const getIcon = (isSelected: boolean) => {
    return {
      path: window.google.maps.SymbolPath.FORWARD_CLOSED_ARROW,
      scale: 6,
      fillColor: isSelected ? "#3b82f6" : "#10b981", // Blue if selected, Green otherwise
      fillOpacity: 1,
      strokeWeight: 2,
      strokeColor: "#ffffff",
      rotation: 0, // In a real app, use driver.heading
    };
  };

  if (!apiLoaded) {
    // FALLBACK SIMULATION MAP (If no API Key provided)
    return <FallbackMap drivers={drivers} selectedDriverId={selectedDriverId} onSelectDriver={onSelectDriver} />;
  }

  return <div ref={mapRef} className="w-full h-full" />;
};

// --- FALLBACK VISUALIZATION ---
// This ensures the app is usable immediately without configuring an API key
const FallbackMap: React.FC<MapProps> = ({ drivers, selectedDriverId, onSelectDriver }) => {
  // Projection centered on Antigua
  // Center Lat: 17.07, Center Lng: -61.81
  const centerLat = 17.07;
  const centerLng = -61.81;
  const scale = 5000; // Adjusted for smaller island scale

  return (
    <div className="w-full h-full bg-[#1e293b] relative overflow-hidden group">
      {/* Abstract Island Shape for Antigua */}
       <svg className="absolute top-1/2 left-1/2 transform -translate-x-1/2 -translate-y-1/2 w-[80%] h-[80%] opacity-10 pointer-events-none" viewBox="0 0 200 200">
          <path fill="currentColor" className="text-emerald-400" d="M60,80 Q70,50 100,60 Q130,50 150,80 Q160,110 140,140 Q110,160 80,150 Q50,140 40,110 Z" /> 
          <path fill="currentColor" className="text-emerald-600" d="M50,120 Q60,150 90,140 Q70,130 50,120 Z" opacity="0.5" />
      </svg>

      {/* Tech Grid Pattern */}
      <div className="absolute inset-0 opacity-20" 
           style={{ backgroundImage: 'linear-gradient(#475569 1px, transparent 1px), linear-gradient(90deg, #475569 1px, transparent 1px)', backgroundSize: '40px 40px' }}></div>

      {/* Simulation Text */}
      <div className="absolute top-4 left-4 z-10 bg-black/50 backdrop-blur px-3 py-1 rounded text-xs text-slate-400 border border-slate-700 shadow-lg">
        <span className="text-emerald-500 font-bold">●</span> Demo Mode (Antigua)
      </div>

      {/* Render Drivers */}
      {drivers.filter(d => d.isOnline).map(driver => {
        const x = 50 + (driver.longitude - centerLng) * scale / 10; // % offset
        const y = 50 - (driver.latitude - centerLat) * scale / 6; // % offset
        const isSelected = driver.id === selectedDriverId;

        let markerColor = 'bg-blue-600';
        if (driver.status === 'DELIVERED') markerColor = 'bg-emerald-500';
        if (driver.status === 'DELAYED') markerColor = 'bg-amber-500';

        return (
          <button
            key={driver.id}
            onClick={() => onSelectDriver(driver.id)}
            className="absolute transform -translate-x-1/2 -translate-y-1/2 transition-all duration-1000 ease-linear hover:scale-110 z-20"
            style={{ left: `${x}%`, top: `${y}%` }}
          >
            <div className={`relative flex items-center justify-center w-8 h-8 rounded-full shadow-lg border-2 ${isSelected ? 'border-white z-30 scale-125' : 'border-transparent'} ${markerColor}`}>
               <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 text-white" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
              {/* Pulse effect */}
              {isSelected && <span className={`absolute inline-flex h-full w-full rounded-full opacity-75 animate-ping ${markerColor}`}></span>}
            </div>
            <div className="absolute top-10 left-1/2 -translate-x-1/2 bg-slate-900/90 text-white text-[10px] px-2 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap border border-slate-700">
              {driver.name}
            </div>
          </button>
        );
      })}
    </div>
  );
};
